  },
  {
    "key": "rqLetterBlurb",
    "en": "Say",
    "fr": "Dire"
  },
  {
    "key": "rqLetterLine",
    "en": "\"There is post for me in the post box! Bring it to my door, and say something nice when you get there.\"",
