    "fr": "{b} fait exactement ce que tu dis, un pas après l’autre : avancer, tourner, remplir, arroser, ramasser, poser."
  },
  {
    "key": "n2",
    "en": "Repeat",
    "fr": "Répéter"
  },
  {
    "key": "n2p",
    "en": "Do the same dance several times, without saying it several times.",
    "fr": "Faire la même danse plusieurs fois, sans la dire plusieurs fois."
  },
  {
    "key": "n3",
    "en": "Repeat until",
    "fr": "Répéter jusqu’à"
  },
  {
    "key": "n3p",
    "en": "Keep going until something is true, like reaching the wall.",
    "fr": "Continuer jusqu’à ce que quelque chose soit vrai, comme toucher le mur."
  },
  {
    "key": "n4",
    "en": "If",
