  },
  {
    "key": "n4p",
    "en": "Only do it when something is true: water only if a tulip is ahead.",
    "fr": "Le faire seulement si c’est vrai : arroser seulement s’il y a une tulipe devant."
  },
  {
    "key": "n5",
    "en": "When",
    "fr": "Quand"
  },
  {
    "key": "n5p",
    "en": "Start when something happens: when Biscuit meows, go to the bowl.",
    "fr": "Démarrer quand quelque chose arrive : quand Biscuit miaule, aller à la gamelle."
  },
  {
    "key": "n6",
    "en": "Counting",
    "fr": "Compter"
  },
  {
    "key": "n6p",
    "en": "{b} keeps a number in mind, like how many eggs are in the basket.",
    "fr": "{b} garde un nombre en tête, comme le nombre d’œufs dans le panier."
  },
  {
    "key": "n7",
    "en": "A trick with a name",
    "fr": "Une astuce avec un nom"
  },
  {
    "key": "n7p",
    "en": "Bundle steps into one new block, like \"water a row\", and use it anywhere.",
    "fr": "Regrouper des pas dans un nouveau bloc, comme « arroser une rangée », et l’utiliser partout."
  },
