  },
  {
    "key": "guTitle",
    "en": "Olive, offline",
    "fr": "Olive, hors ligne"
  },
  {
    "key": "guSub",
    "en": "Olive is the helper owl. Her hints come from the game’s own rules. A small language model, stored on this computer, only puts them into friendly words and writes the islanders’ thank-yous.",
    "fr": "Olive est la chouette qui aide. Ses indices viennent des règles du jeu. Un petit modèle de langage, stocké sur cet ordinateur, ne fait que les formuler gentiment et écrire les mercis des habitants."
  },
  {
    "key": "guWhereH",
    "en": "Where Olive lives",
    "fr": "Où habite Olive"
  },
  {
    "key": "guNoModel",
    "en": "No model at all. The game still works: Olive uses her written lines.",
    "fr": "Aucun modèle. Le jeu marche quand même : Olive utilise ses phrases écrites."
  },
  {
    "key": "guRulesH",
    "en": "What Olive is allowed to do",
    "fr": "Ce qu’Olive a le droit de faire"
  },
  {
    "key": "guR1",
    "en": "Say a hint in her own words. The hint itself is decided by the game, not by the model.",
    "fr": "Dire un indice avec ses mots. L’indice lui-même est décidé par le jeu, pas par le modèle."
  },
  {
    "key": "guR2",
    "en": "Write a thank-you or a greeting for an islander, in French or English, under 25 words.",
    "fr": "Écrire un merci ou un bonjour pour un habitant, en français ou en anglais, en moins de 25 mots."
  },
  {
    "key": "guR3",
    "en": "Never place a block, never solve a request, never talk about anything outside the island.",
    "fr": "Ne jamais poser un bloc, ne jamais résoudre une demande, ne jamais parler d’autre chose que de l’île."
  },
  {
    "key": "guR4",
    "en": "Every line is checked against a word list before it is shown. A refused line falls back to a written one.",
    "fr": "Chaque phrase est vérifiée avec une liste de mots avant d’être montrée. Une phrase refusée est remplacée par une phrase écrite."
  },
  {
    "key": "guDataH",
    "en": "Nothing leaves the house",
    "fr": "Rien ne sort de la maison"
  },
  {
    "key": "guD1",
    "en": "No account, no internet, no adverts. The game is installed like any other program.",
    "fr": "Pas de compte, pas d’internet, pas de pub. Le jeu s’installe comme n’importe quel programme."
  },
  {
    "key": "guD2",
    "en": "Saved on this computer. A save code moves the family’s islands to another computer.",
    "fr": "Sauvegardé sur cet ordinateur. Un code de sauvegarde déplace les îles de la famille vers un autre ordinateur."
  },
  {
    "key": "guD3",
    "en": "No timers, streaks, points or \"you missed a day\". Rewards are cosmetic and always earnable.",
    "fr": "Pas de chrono, de série, de points ni de « tu as raté un jour ». Les récompenses sont décoratives et toujours gagnables."
  },
